# -*- coding: utf-8 -*-
# NEW cross-platform combinations. Numbering continues from SE-016.
COMBOS_SHALLOW = [
 dict(id="SE-017", ways=2, name="The Money Stress Early Warning",
  parents="Dr. Buddy 09 (Crisis Detection) + RCS 008 (Behavioral Lock-In Detection)",
  metaphor="a smoke detector wired to the fuse box instead of the ceiling",
  simple="Most smoke alarms wait for smoke. Imagine one wired straight into the fuse box, noticing the wire heating up an hour before anything burns. This invention watches for the moment a person's money decisions start bending under emotional pressure, before the bad decision is made. It is not reading their mood and it is not reading their bank balance; it is watching the shape of the two moving together. When the pattern tightens, someone is told while there is still time to talk.",
  works="One side tracks the small signals that come before a mental health crisis; the other tracks the small signals that come before a panic financial move, like cashing out at the bottom. Alone, each is often a false alarm. Read against each other, a rise in both at once is far more meaningful than either on its own, and the system only speaks when both bend in the same direction at the same time.",
  patentable="Nobody has used psychiatric crisis prediction as the confirming signal for financial behaviour prediction. The emergent capability is a warning that arrives before the irreversible money decision rather than in the statement afterward, with a false-alarm rate low enough that an advisor will actually act on it.",
  alice=8, alice_why="Two independent time-series signals gated against each other is a specific technical improvement in signal quality, not a mental process.",
  priority="Critical to file",
  urgency="This is the single most valuable idea in the cross-platform set because it prevents losses rather than reporting them. Both parent mechanisms already exist in code, so the combination is buildable immediately and therefore obvious to a competitor who holds both. It also sits on the border between two industries that rarely talk, which is exactly where the strongest claims live and where nobody has filed. Every month unfiled is a month a health-tech or fintech company could arrive at the same junction independently."),
 dict(id="SE-018", ways=2, name="The Honest Sales Room",
  parents="JoinAQAL PAT-007 (Honest Mechanics Transparency) + RCS 003 (AI Whisper Coaching)",
  metaphor="a teleprompter that refuses to display a line the speaker cannot back up",
  simple="Picture a teleprompter that goes blank the instant the speaker tries to read something that is not true. Not a warning light, just nothing to read. This invention sits in a live advisor meeting and only feeds the advisor claims the system can actually stand behind. If the maths does not support the sentence, the sentence never appears. The advisor is left saying only what the platform can prove.",
  works="During a meeting, the coaching side offers the advisor suggested lines in real time. Before any line is shown, the transparency side checks whether the underlying computation supports it and at what confidence. Weak support means the line is withheld or rewritten to a narrower claim. The advisor never sees the rejected version, so there is nothing to be tempted by.",
  patentable="Sales-assist tools optimise for persuasion; this one subordinates persuasion to provability inside the same live loop. The emergent capability is an advisor who is mechanically prevented from over-claiming in the moment, which no compliance review after the fact can achieve.",
  alice=8, alice_why="A real-time suppression gate between two engines is technical; the claim must avoid reading as 'give good advice'.",
  priority="Critical to file",
  urgency="The Bonner call audit shows precisely what this prevents: sixteen minutes of over-claiming that closed a live prospect's door. That makes the need demonstrable with your own evidence, which strengthens the application considerably. Sales-assist AI is the most crowded space in this portfolio, so first-to-file matters more here than anywhere else. Build and file together while you still have a clean record of the problem it solves."),
 dict(id="SE-019", ways=2, name="Proof That Only Climbs",
  parents="JoinAQAL PAT-004 (Weakness Identification) + Dr. Buddy 12 (Neuroplasticity Training)",
  metaphor="a high-water mark carved into a harbour wall",
  simple="Harbours carve the highest tide into the stone, and that mark never moves down no matter how calm the sea gets later. This invention does the same for a person's proven ability. Once someone has genuinely demonstrated a level, it is carved in, and a bad week cannot erase it. Training is then aimed at the one thing holding them back rather than at whatever they happened to score badly on today. The floor rises; it never falls.",
  works="The weakness side finds the single ability doing the most damage to everything else. The training side builds exercises aimed at that one thing. New results can only raise the recorded mark, never lower it, so a poor day is treated as noise rather than as loss. Each time the mark rises, the weakness is recalculated and training re-aims.",
  patentable="Adaptive training normally lets scores drift both ways, which lets short-term variance redirect a long-term programme. The emergent capability is a training loop that cannot be derailed by a bad day, because its target only updates on proven improvement.",
  alice=7, alice_why="The monotonic update rule is a concrete algorithmic constraint; the surrounding training idea is well-trodden and needs narrow claiming.",
  priority="High importance",
  urgency="Both halves are already implemented, so this is close to free to demonstrate. The ratchet rule is the genuinely novel part and it is easy to describe, which cuts drafting cost. Educational technology moves fast and monotonic proof scoring is an idea whose time is arriving. File alongside the other JoinAQAL work so the family shares an early date."),
 dict(id="SE-020", ways=2, name="The Plan That Reads The Room",
  parents="Dr. Buddy 11 (Therapeutic Alliance) + Drass DR-03 (One Identity, Two Faces)",
  metaphor="a translator who changes register, not meaning, between a courtroom and a kitchen table",
  simple="A good translator says the same true thing differently to a judge and to a worried family at a kitchen table. The facts do not move; the register does. This invention gives the advisor and the client the same financial truth in two different voices, chosen by who is signed in. Nobody gets a softened number. They get the number in the language that will actually land.",
  works="The identity layer already knows whether the person reading is an advisor or a client. The alliance model, borrowed from therapy, adjusts tone, pacing and how much is said at once to suit that reader. The underlying figures are identical and are drawn from the same computation, so the two views can be laid side by side without contradiction. Only the delivery changes.",
  patentable="Personalisation systems normally change what is shown; this one holds the content fixed and varies only the delivery, using a clinical alliance model in a financial setting. The emergent capability is two audiences receiving genuinely identical information without either being condescended to or overwhelmed.",
  alice=6, alice_why="Presentation adaptation is close to abstract; survives only if claimed on the verified-role input and the fixed-content guarantee.",
  priority="Moderate",
  urgency="The weakest of the two-way group on eligibility, so it should not lead a filing. It is worth including as a dependent claim inside a stronger application rather than standing alone. Its commercial pull is real, because advisors will pay for anything that reduces client confusion. Hold it until the identity patent is filed and attach it there."),
 dict(id="SE-021", ways=3, name="The Whole Person Ledger",
  parents="JoinAQAL PAT-001 (8-Model Consensus) + Dr. Buddy 10 (Mental Health Vital Signs) + RCS 004 (Wealth Genome)",
  metaphor="three surveyors triangulating a mountain none of them can see the whole of",
  simple="One surveyor guessing a mountain's height is guessing. Three, standing far apart and comparing angles, get an answer none could reach alone. This invention takes three completely separate readings of a person, how they think, how they are holding up, and how they behave with money, and triangulates a single picture. No one reading is trusted on its own. The overlap is the answer.",
  works="Each side measures on its own terms and produces its own confidence. The system looks for where the three agree and, more usefully, where they disagree, because a sharp disagreement is itself information about the person. The combined picture carries the disagreements forward rather than averaging them away. Everything is written into a record that can be added to but never rewritten.",
  patentable="Nothing on the market measures cognition, mental health and financial behaviour as three independent instruments and treats their disagreement as signal. The emergent capability is a profile that can say not just what a person is like but how confident it is, and exactly where the evidence conflicts.",
  alice=8, alice_why="Multi-instrument triangulation with preserved disagreement is a concrete data-fusion improvement, well clear of abstract profiling.",
  priority="Critical to file",
  urgency="This is the spine that every four-way and larger combination hangs from, so its priority date protects far more than itself. All three parents exist in working code today, which makes the application unusually well supported. Preserving disagreement rather than averaging is the non-obvious step and it is easy to lose if someone else files a simpler fusion claim first. This should go in the first batch without exception."),
 dict(id="SE-022", ways=3, name="Retirement With The Brakes Checked",
  parents="RCS 007 (Ecological Drivers Retirement Risk) + Dr. Buddy 01 (Dual-Path Trajectory) + JoinAQAL PAT-003 (Stage-Band Reporting)",
  metaphor="a mountain guide who checks the weather, the rope and the climber, not just the map",
  simple="A good guide does not only read the route. They check the sky, the gear, and the person standing in front of them. This invention plans a retirement the same way: the market risks, the health path ahead, and where the person actually is in their own development. It gives a range rather than a single confident number, because a guide who promises an exact arrival time is lying. The plan changes when any of the three change.",
  works="One side models the outside dangers to the money over time. Another models two futures for the person, one where health holds and one where it does not. The third places the person on a developmental band with an honest margin. The three are run together so the plan reflects the person walking the route, not an average person.",
  patentable="Retirement planning treats the human as a set of balances and a life expectancy. Running a dual health trajectory and a developmental band as first-class inputs to the risk model is new. The emergent capability is a plan whose confidence interval reflects the person's own likely path rather than a population table.",
  alice=7, alice_why="Coupled simulation across heterogeneous models is technical, but the claim must not drift into 'financial planning, computerised'.",
  priority="High importance",
  urgency="Retirement risk is the most commercially proven surface you have, so protection here converts directly to revenue. The health-trajectory input is what makes it novel and it is also what a large incumbent would most plausibly add next. Both the financial and the clinical parents are documented, making the application straightforward. File in the first batch or the second at the latest."),
 dict(id="SE-023", ways=3, name="The Tool That Knows When To Stay Shut",
  parents="Drass DR-02 (Refuse-Before-Render) + RCS 010 (Time Machine Dual-Illustration) + JoinAQAL PAT-007 (Honest Mechanics)",
  metaphor="a drawbridge that will not lower while a ship is still in the channel",
  simple="A drawbridge that lowers on schedule regardless of the water below is a disaster waiting to happen. The safe one refuses until the channel is clear. This invention refuses to show a what-would-have-happened illustration until the conditions for showing it honestly are met. Backward-looking illustrations are the easiest way to mislead someone, so this one will not draw at all rather than draw carefully. The refusal explains itself in plain words.",
  works="Before a historical illustration is built, the compliance gate tests whether this specific comparison is fair, given its assumptions and the period chosen. The transparency layer supplies what the person would need to know to judge it. If either is unsatisfied, nothing is drawn and the reason appears instead. When it does draw, both the figures and the reasoning behind them arrive together.",
  patentable="Historical illustration tools attach disclaimers to output that already exists. Here the ability to generate is conditioned on fairness being established first, and the explanation is produced by the same pass that produces the figures. The emergent capability is a backward-looking illustration that cannot be shown in a misleading configuration.",
  alice=8, alice_why="Conditional generation with a coupled explanation pass is a specific mechanism and sits comfortably on the technical side.",
  priority="Critical to file",
  urgency="Backward-looking illustrations are the highest-risk thing any financial site displays and the most likely to draw regulatory attention. A filed claim here is both protection and evidence of good faith if anyone ever asks. The mechanism is already partly built inside the Drass plugin, which means public exposure has begun. File this with the compliance gate as one family."),
 dict(id="SE-024", ways=4, name="The Four-Corner Reading",
  parents="JoinAQAL PAT-002 (Voice Analysis) + Dr. Buddy 03 (Multi-Modal Intake) + RCS 003 (Whisper Coaching) + Drass DR-04 (Patent 360)",
  metaphor="a ship's navigator taking bearings on four lighthouses at once",
  simple="A navigator with one lighthouse knows a direction. With four, they know exactly where the ship is. This invention takes a reading of a live conversation from four directions at once: how the person's voice sounds, what their intake says, what the advisor is being told to do, and which engines are running underneath. It fixes a position no single reading could give. And it records the bearings so the fix can be checked later.",
  works="While a person is speaking, the voice side measures how they are saying it and the intake side measures what they are saying. The coaching side uses both to decide what the advisor should do next. The console records which protected engine produced each of those decisions, in order, as it happens. The result is a conversation that can be replayed afterward with its reasoning intact.",
  patentable="No system reads a live financial conversation through clinical intake, prosody, sales coaching and its own provenance trail at once. The emergent capability is a meeting that leaves behind a defensible record of why each thing was said, which is valuable for training, compliance and litigation alike.",
  alice=7, alice_why="Strong on the synchronised multi-source capture; the provenance component should be claimed as part of the loop, not as reporting.",
  priority="High importance",
  urgency="This is the first combination that genuinely requires all four platforms, which makes it a natural anchor for the four-way family. It is also the one most likely to be demonstrated to prospects, and demonstrations are public use. The Bonner audit already shows the shape of the output, giving the application concrete support. File once the voice wiring has run against real calls."),
 dict(id="SE-025", ways=4, name="The Free Door Between Houses",
  parents="Drass DR-03 (One Identity) + JoinAQAL PAT-006 (Integral Framework) + Dr. Buddy 13 (Integrated Platform) + RCS 001 (Cascading Recalculation)",
  metaphor="a row of terraced houses with every internal wall doored, and no rent charged to walk through",
  simple="Imagine four houses in a row where every dividing wall has a door, and walking through costs nothing. You unlock the front door once and the whole row is yours. This invention makes four separate platforms behave like four rooms of one home, at no charge to the person walking between them. What they do in one room updates the others while they are still walking. Nobody has to sign in again or explain themselves twice.",
  works="One verified sign-in is honoured by all four platforms. A change made in any of them is announced to the others, and the connected calculators recompute in the right order rather than all at once. The integral framework decides which of a person's many aspects a given update actually touches, so unrelated parts are left alone. The person experiences one place that happens to be very large.",
  patentable="Cross-platform single sign-on exists; what does not exist is a four-way arrangement where a change in one domain triggers ordered recomputation in the others under a shared model of the person. The emergent capability is that cognitive, clinical and financial states stay consistent with each other without anyone reconciling them by hand.",
  alice=7, alice_why="The ordered cross-domain recomputation is the technical heart; claim that rather than the sign-on, which is crowded art.",
  priority="High importance",
  urgency="This is the invention that makes 'they all work together and it is all free' true rather than a slogan, so it protects the core promise of the offer. It is also the piece a large platform company would build if it decided to enter this space. The cascade ordering is subtle and hard to reinvent, which makes the claim durable. File in the second batch, directly after the identity patent."),
 dict(id="SE-026", ways=4, name="Advice With Its Receipts Attached",
  parents="RCS 005 (Income Waterfall) + JoinAQAL PAT-005 (Coaching Synthesis) + Dr. Buddy 14 (PubMed Research) + Drass DR-04 (Patent 360)",
  metaphor="a chef who sends the market receipts out with every dish",
  simple="Imagine a restaurant that plates your dinner and lays the morning's market receipts beside it, showing where each ingredient came from. You can eat without reading them, but they are there. This invention delivers a financial recommendation with its sources attached: the research behind it, the models that shaped it, and the order the money should move. Anyone can trace the dish back to the market. Nothing is asserted without a paper trail.",
  works="The waterfall side works out the sequence money should be drawn in. Several coaching models propose how to present and stage it. The research side attaches the strongest published evidence for each element. The console records which engines produced which part, so the finished recommendation carries its own provenance rather than having it assembled afterward.",
  patentable="Financial recommendations cite sources rarely and never automatically at the level of the individual step. The emergent capability is advice where every component can be traced to both the published evidence and the specific engine that produced it, generated in the same pass as the advice itself.",
  alice=8, alice_why="Per-step provenance generated inline with the recommendation is a genuine technical mechanism, not a citation convention.",
  priority="Critical to file",
  urgency="Regulators are moving steadily toward demanding exactly this kind of traceability from advice software. Being first here is both a patent position and a licensing wedge into firms that will soon be required to comply. The mechanism is unusual because the provenance is produced with the advice rather than reconstructed, and that distinction is the whole claim. It should not wait for the second batch."),
]
